sys_script_include.script:
var GetAssessmentStatus = Class.create();
GetAssessmentStatus.prototype = {
    initialize: function() {
    },

    getStatus: function(assetSysId) {
        var latestRecord = new GlideRecord('x_1440356_riskatla_asset_risk_evaluation');
        latestRecord.addQuery('asset_id', assetSysId);
        latestRecord.orderByDesc('sys_created_on');
        latestRecord.setLimit(1);
        latestRecord.query();

        if (latestRecord.next()) {
            gs.addInfoMessage('Latest related record: ' + latestRecord.getDisplayValue());
            return latestRecord.assessment_status;
        }

        return null; // or a default value if no record is found
    },

    type: 'GetAssessmentStatus'
};
